export type ProGroupId = 'eu' | 'na' | 'af' | 'monde';
export type ProCurrency = 'EUR' | 'USD' | 'XOF';
export type ProMode = 'avion' | 'bateau' | 'standard';
export type ProStatus = 'disponible' | 'bientot' | 'programme' | 'hors_saison';
export type ProGroupPrice = { offered: boolean; EXW: number | null; FOB: number | null };
export type ProException = { countries: string[]; offered: boolean; EXW: number | null; FOB: number | null };
export type ProOffer = {
  mode: ProMode;
  active: boolean;
  min: number | null;
  step: number | null;
  max: number | null;
  groups: Record<ProGroupId, ProGroupPrice>;
  exceptions: ProException[];
};
export type ProMedia = { kind: 'photo' | 'video'; url: string; poster?: string; caption: string; ratio?: number };
export type ProSheet = {
  status: ProStatus;
  campaign: { start: string | null; end: string | null };
  volume: { amount: number; unit: 'tonnes' | 'conteneurs' } | null;
  varieties: string[];
  calibres: string[];
  packaging: string;
  quality: string;
  offers: ProOffer[];
  countries: { mode: 'all' | 'pays' | 'sauf'; list: string[] };
  logistics: { port: string; airport: string; station: string };
  terms: string;
  globalgap: boolean;
  media: ProMedia[];
  programmes: boolean;
};
export type ProOfferView = { mode: ProMode; currency: ProCurrency; EXW: number | null; FOB: number | null; min: number | null; step: number | null; max: number | null; unit: 'kg' | 'conteneur' };

export const PRO_GROUPS: { id: ProGroupId; label: string; currency: ProCurrency }[];
export const PRO_GROUP_IDS: ProGroupId[];
export const PRO_SIGN: Record<ProCurrency, string>;
export const PRO_EUROPE: string[];
export const PRO_NORTH_AMERICA: string[];
export const PRO_AFRICA: string[];
export function proGroupOf(country: string | null | undefined): ProGroupId;
export function proCurrencyOf(country: string | null | undefined): ProCurrency;
export const PRO_MODES: ProMode[];
export const PRO_MODE_LABEL: Record<ProMode, string>;
export function proQtyUnit(mode: ProMode): 'kg' | 'conteneur';
export const PRO_STATUSES: { id: ProStatus; label: string }[];
export function proStatusLabel(id: string): string;
export const PRO_VOLUME_UNITS: ('tonnes' | 'conteneurs')[];
export const PRO_COUNTRY_MODES: ('all' | 'pays' | 'sauf')[];
export const PRO_LIMITS: { tags: number; tag: number; packaging: number; quality: number; place: number; terms: number; media: number; caption: number; exceptions: number };
export const PRO_PRICE_MAX: Record<ProCurrency, number>;
export function emptyGroups(): Record<ProGroupId, ProGroupPrice>;
export function emptyPro(defaults?: { terms?: string; port?: string; airport?: string; station?: string }): ProSheet;
export function validatePro(input: unknown): { errors: Record<string, string>; warnings: string[]; value: ProSheet };
export function proSoldIn(pro: ProSheet | null | undefined, country: string): boolean;
export function proOfferFor(offer: ProOffer, country: string): ProOfferView | null;
export function proOffersFor(pro: ProSheet | null | undefined, country: string): ProOfferView[];
export function proToDoc(pro: ProSheet | null | undefined): unknown;
export function proPriceText(n: number | null | undefined, currency: ProCurrency): string;
